// HasAuthorizedByWith applies the HasEdge predicate on the "authorized_by" edge with a given conditions (other predicates).
func HasAuthorizedByWith(preds ...predicate.User) predicate.QuickConnectRequest {
	return predicate.QuickConnectRequest(func(s *sql.Selector) {
		step := newAuthorizedByStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.QuickConnectRequest) predicate.QuickConnectRequest {
	return predicate.QuickConnectRequest(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.QuickConnectRequest) predicate.QuickConnectRequest {
	return predicate.QuickConnectRequest(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.QuickConnectRequest) predicate.QuickConnectRequest {
	return predicate.QuickConnectRequest(sql.NotPredicates(p))
}
